// Сгенерировано: npm run embed-assets. Не править руками: правьте файлы в assets/ и запустите команду снова.
// Ресурсы плагина вшиты в index.mjs; installAssets кладёт их в каталог данных плагина (docs/guide/authors/assets.md).
import type { PluginOs } from '@cyborg-harness/contracts';

/** Ресурсы: путь внутри assets/ (без .txt у исходных расширений) -> текст. */
export const ASSETS: Readonly<Record<string, string>> = {
  ".claude-plugin/plugin.json": "{\n  \"name\": \"cyborg\",\n  \"description\": \"Скиллы и хуки Cyborg для сессий, запущенных из него: работа в параллельных сессиях, перезапуск LSP после смены или снятия worktree.\",\n  \"version\": \"0.1.0\"\n}\n",
  "hooks/hooks.json": "{\n  \"hooks\": {\n    \"PostToolUse\": [\n      {\n        \"matcher\": \"EnterWorktree|ExitWorktree|Bash\",\n        \"hooks\": [\n          {\n            \"type\": \"command\",\n            \"command\": \"bash \\\"${CLAUDE_PLUGIN_ROOT}/hooks/lsp-reap.sh\\\" 2>/dev/null || true\",\n            \"timeout\": 10\n          }\n        ]\n      }\n    ]\n  }\n}\n",
  "hooks/lsp-reap.sh": "#!/usr/bin/env bash\n# LSP Claude Code не следует за сменой каталога сессии; убитый, он поднимется заново в текущем cwd при следующем вызове.\nset -u\n[ -d /proc/self ] || exit 0\n\ninput=$( [ -t 0 ] || cat )\nfield() { printf '%s' \"$input\" | grep -o \"\\\"$1\\\":\\\"[^\\\"]*\\\"\" | head -1 | sed 's/^\"[^\"]*\":\"//; s/\"$//'; }\n\nLSP_NAME='language-?server|langserver|-ls$|^(gopls|rust-analyzer|clangd|jdtls|pylsp|tsserver(\\.js)?|OmniSharp)$'\n\nargv() { tr '\\0' '\\n' < /proc/\"$1\"/cmdline 2>/dev/null | head -2; }\nis_lsp() {\n  local a\n  while IFS= read -r a; do [[ ${a##*/} =~ $LSP_NAME ]] && return 0; done < <(argv \"$1\")\n  return 1\n}\nis_claude() {\n  [ \"$(cat /proc/\"$1\"/comm 2>/dev/null)\" = claude ] && return 0\n  argv \"$1\" | grep -qE '(^|/)claude$|claude-code/cli\\.js$'\n}\nsession_of() {\n  local p=$1\n  while [ \"${p:-0}\" -gt 1 ]; do\n    is_claude \"$p\" && { echo \"$p\"; return; }\n    p=$(awk '{print $4}' /proc/\"$p\"/stat 2>/dev/null)\n  done\n}\ntree() {\n  echo \"$1\"\n  local c\n  for c in $(pgrep -P \"$1\"); do tree \"$c\"; done\n}\n\ntool=$(field tool_name)\nhere=$(field cwd)\nmoved=\ncase $tool in EnterWorktree|ExitWorktree) [ -n \"$here\" ] && moved=1 ;; esac\n\nif [ \"${1:-}\" = --all ]; then\n  roots=$(pgrep -u \"$(id -u)\" -x claude)\n  moved=\nelse\n  roots=${LSP_REAP_ROOT:-$(session_of \"$PPID\")}\nfi\n[ -n \"$roots\" ] || exit 0\n\nreaped=()\nfor root in $roots; do\n  for p in $(pgrep -P \"$root\"); do\n    is_lsp \"$p\" || continue\n    cwd=$(readlink /proc/\"$p\"/cwd 2>/dev/null) || continue\n    case $cwd in\n      *' (deleted)') ;;\n      \"$here\") continue ;;\n      *) [ -n \"$moved\" ] || continue ;;\n    esac\n    kill -TERM $(tree \"$p\") 2>/dev/null\n    reaped+=(\"$p ${cwd% (deleted)}\")\n  done\ndone\n\n[ ${#reaped[@]} -eq 0 ] && exit 0\nmsg=$(printf '%s; ' \"${reaped[@]}\")\nmsg=\"LSP перезапустится в текущем каталоге, остановлен прежний: ${msg%; }\"\nmsg=${msg//\\\\/\\\\\\\\}\nprintf '{\"systemMessage\":\"%s\"}\\n' \"${msg//\\\"/\\\\\\\"}\"\n",
  "skills/parallel-sessions/SKILL.md": "---\nname: parallel-sessions\ndescription: Как сессия Cyborg делегирует части своей задачи другим сессиям, локальным и удалённым (агенты на серверах по SSH), решает задачу с ними совместно и закрывает отработавших - инструменты open_session, spawn_agent, list_sessions, send_to_session, report_done, close_session, close_agent. Используй, когда задача распадается на независимые части, нужны долгий прогон, независимая проверка или параллельные гипотезы, когда человек дал несколько заданий, просит «сделай параллельно», «разнеси по сессиям», «запусти агента на сервере» или спрашивает, что делают соседние вкладки.\n---\n\n# Параллельные сессии Cyborg\n\nCyborg держит в проекте несколько вкладок, в каждой - своя сессия Claude Code. Ты можешь открыть соседнюю вкладку, отдать ей часть работы и забрать итог. Соседка работает одновременно с тобой и этого диалога не видит. Открытая тобой вкладка - твоя дочерняя, ты за неё отвечаешь до закрытия; в `list_sessions` у неё `child: true`, у всякой открытой инструментом - `parent`, номер открывшей.\n\n| | Локальная сессия | Удалённый агент |\n|---|---|---|\n| Открывает | `open_session` | `spawn_agent` (есть, если в проекте заданы хосты) |\n| Где работает | эта машина; основной каталог читает как есть, правит в своём worktree | сервер по SSH, свои клоны `origin` |\n| Что видит из твоей работы | ветку, которую ты назвал в задании, - иначе её worktree встанет на `origin` | запушенное в `origin` |\n| Чем сдаёт итог | коммит в своей ветке и `report_done` - итог приходит тебе сообщением сам | ветка, PR и `report_done` - итог приходит тебе сообщением сам |\n| Закрывает | `close_session` | `close_agent` - заодно убирает клоны на хосте |\n\nВ `list_sessions` у удалённой вкладки есть `host`, у локальной его нет.\n\n## Цель\n\nЗадача решается с наименьшей общей ценой: время до результата, токены всех участвующих сессий, прогоны сборки и тестов, место на площадках. Делегирование - средство: часть уходит другой сессии, только если так выходит дешевле или быстрее, чем сделать самому. Цена новой сессии - заново прочитанные инструкции и код, свой worktree, приёмка и слияние итога; каждое сообщение будит получателя на полный ход. Часть, которая ничего не правит и нужна только выводом, дешевле отдать субагенту (`Agent`), чем вкладке.\n\n## 1. Решение человека\n\nСначала прочитай память: решение о делегировании другим сессиям могло быть принято раньше.\n\n- Записано «согласен» - делегируй по своему усмотрению без вопроса, человеку назови раскладку.\n- Записано «отказался» - веди задачу сам и не предлагай.\n- Записи нет - предложи: какие части независимы и какая в какую сессию уйдёт. Сессии открывай после согласия.\n\nОтвет человека сохрани в постоянную память одной записью: согласен или нет, дата, оговорки («только для ревью», «не больше трёх сессий»). Постоянной памяти нет - решение действует до конца этой сессии.\n\n## 2. Что можно и чего нельзя\n\nМожно, в рамках решения человека:\n- отдать часть задачи - правку, прогон, расследование, ревью, гипотезу - новой сессии либо дописать её своей дочерней, у которой нужный контекст уже загружен;\n- вести задачу совместно: дочерние спрашивают тебя и друг друга, если ты связал их в задании;\n- закрыть дочернюю, чья часть больше не нужна, в любом её состоянии.\n\nНельзя:\n- отдавать одновременно части, зависящие друг от друга: одна ждёт результата другой или правит её файлы. Такие части - одной сессии либо по очереди;\n- дочерней - открывать свои сессии, если задание этого не разрешило;\n- слать сообщения, после которых получателю нечего делать: подтверждение, промежуточный отчёт;\n- гонять один и тот же прогон в нескольких сессиях: дочерняя проверяет то, что поменяла сама, полный набор гейтов после слияния - один раз, у тебя;\n- держать дочернюю, которая не сходится: упёрлась - сдаёт выясненное и причину, а не перебирает до лимита.\n\n## 3. Где запускать: нагрузка\n\nПеред раздачей вызови `list_sessions` и посчитай нагрузку по площадкам: эта машина (вкладки без `host`) и каждый хост из перечня `host` у `spawn_agent`. Чужие вкладки тоже считаются - площадку они занимают так же.\n\n- Занятость площадки - число её вкладок в `working` и `starting`. Вкладки в `waiting` и `asking` процессор не грузят, но место в пределе хоста занимают.\n- Каждую новую часть - на наименее занятую площадку из подходящих. При равенстве чередуй площадки. Раздавай по одной и пересчитывай.\n- Предел хоста - 4 агента по умолчанию; агент сверх предела закроется с итогом `failed`. `limits` не поднимай, пока человек не сказал.\n- Все площадки заняты - не уплотняй: остальное ставь в очередь и раздавай по мере прихода итогов.\n\nПодходит площадка или нет, решает часть:\n- нужна незапушенная работа - только локальная сессия: закоммить её в свою ветку и назови ветку в задании; незакоммиченное до дочерней не дойдёт;\n- долгая сборка, тяжёлый прогон, работа на часы - на хост: эту машину не занимает и переживает закрытие Cyborg;\n- короткая часть с быстрым ответом - локальная сессия: агенту нужны клон и подтверждение человека на запуск и закрытие.\n\nРаскладку - какая часть на какую площадку и почему - назови человеку до запуска.\n\n## 4. Задание дочерней\n\n`open_session` принимает `prompt` и `repo`. `repo` - рабочий каталог дочерней, один из каталогов проекта; остальные подключатся ей сами. Вкладка открывается в фоне.\n\n`spawn_agent` вдобавок принимает `host` и `branch`: рабочий клон агента встаёт на эту ветку, а если её нет в `origin`, она создаётся от ветки по умолчанию. Своя ветка каждому агенту.\n\n`prompt` - всё, что дочерняя узнает о задаче: цель и критерий «готово», который она проверит сама; уже выясненное - пути, ветки, тикет; ветку, от которой ей начать worktree, если ей нужна твоя незапушенная работа (`git worktree add <репозиторий>/.claude/worktrees/<имя> -b <её ветка> <твоя ветка>`, затем `EnterWorktree` с `path`); её граница - какие файлы её, что не трогать; что ей можно из раздела 2 сверх запретов; чем закончить - «закоммить в ветку X» либо «запушь ветку X и открой PR»; итог - вызов `report_done`: что сделано, что прогнано и с каким результатом, что осталось. Итог дочерней приходит тебе сообщением сам, свой номер в задании называть не нужно.\n\nЗадание можно начать слэш-командой. С «-» оно начинаться не может.\n\n## 5. Ожидание и итог\n\nНе опрашивай `list_sessions` в цикле. Заверши ход, когда своя часть сделана: итог дочерней придёт тебе как новая реплика.\n\nДочерняя после итога остаётся открытой, агент занимает место на хосте: `send_to_session` начинает у неё новый круг работы, итог круга она сдаёт снова. Агент, 2 ч ждущий ввода, засыпает - клоны и разговор остаются на хосте.\n\n`list_sessions` показывает состояние:\n- `starting` - запускается либо ждёт подтверждения доверия к каталогу;\n- `working` - работает;\n- `waiting` - ход закончен, в записи хвост её последнего ответа;\n- `asking` - стоит на вопросе, разрешении или лимите и ждёт человека; причина в `reason`. Ответить за человека ты не можешь - скажи ему, какая вкладка ждёт и чего.\n\n`send_to_session` дописывает соседке обычный текст: без слэш-команд, «!» и «#». Работающей он дойдёт в конце её хода, сессиям в `starting` и `asking` не отправляется. Отправителя соседка не знает - называй свой номер, если нужен ответ.\n\nИтог дочерней - утверждение, а не факт: дифф, ветку или PR, которые она назвала, проверь сам, прежде чем сливать или пересказывать человеку.\n\n## 6. Закрытие\n\nОтработавшую дочернюю закрываешь ты: итог принят, слит либо отвергнут, или её часть больше не нужна. `close_session` закрывает свою дочернюю в любом состоянии; чужую вкладку закрывай только по просьбе человека, `force` для неё - тоже только по ней. Диалог закрытой вкладки остаётся в истории проекта.\n\nАгента закрывай `close_agent`: он завершает агента в любом состоянии и удаляет клоны. Клон с незапушенной работой остаётся, его путь на хосте будет в ответе - передай путь человеку.\n\nК концу задачи после тебя не остаётся открытых дочерних, их worktree и веток со слитой работой; что оставлено намеренно - назови человеку.\n\nВ конце назови человеку итог по каждой части: что сделано, где лежит, что осталось открытым.\n",
};

/** Первые 16 знаков sha256 содержимого: изменился ресурс - новый каталог установки, старый не переписывается. */
export const ASSET_VERSION = "767e759b536a3afe";

/**
 * Кладёт ресурсы в `<данные плагина>/assets/<версия>/` и возвращает этот каталог; уже установленную версию не трогает.
 * Файлы без бита исполнения: скрипты вызываются как `bash "$каталог/hooks/x.sh"`.
 */
export async function installAssets(os: Pick<PluginOs, 'fs' | 'paths'>): Promise<string> {
  const dir = `${os.paths.data}/assets/${ASSET_VERSION}`;
  const marker = `${dir}/.installed`;
  const done = await os.fs.stat(marker).then(
    () => true,
    () => false,
  );
  if (done) return dir;
  for (const [name, text] of Object.entries(ASSETS)) {
    const file = `${dir}/${name}`;
    await os.fs.mkdir(file.slice(0, file.lastIndexOf('/')));
    await os.fs.writeText(file, text);
  }
  await os.fs.writeText(marker, ASSET_VERSION);
  return dir;
}
